#!/usr/bin/env python3
# Generated by Claudian.
"""Train the local intent classifier.

    python3 training/train_intent_model.py --epochs 100

WHAT THIS REPLACES
------------------
`core/command_router.py` falls back to a Groq LLM call whenever no skill
matches by regex above 0.85 confidence.  That is a network round trip —
300-500ms — spent purely deciding *which skill to run*, before any actual
work begins.  This model answers the same question locally in single-digit
milliseconds.

ARCHITECTURE
------------
Character n-grams (2-5) + word n-grams (1-2), TF-IDF weighted, into a small
MLP.  Character n-grams matter more than they might seem: input comes from
speech-to-text, so "screenshot" arrives as "screen shot", "scrensht", or
"screenshot please".  Word-level features alone are brittle against that;
character n-grams degrade gracefully.

The class distribution is uneven by design (`conversation` is the catch-all
with 38 examples, `whatsapp_send` has 6), so the loss is class-weighted —
otherwise the model learns to answer "conversation" and coast.
"""

from __future__ import annotations

import argparse
import json
import os
import pickle
import sys
import time
from pathlib import Path

import numpy as np

sys.path.insert(0, str(Path(__file__).parent.parent))

import torch
import torch.nn as nn
from sklearn.feature_extraction.text import TfidfVectorizer
from sklearn.model_selection import train_test_split
from sklearn.preprocessing import LabelEncoder

from ai.intent_augment import flatten_augmented
from ai.intent_dataset import flatten, stats

MODEL_DIR = Path(__file__).parent.parent / "data" / "models"
MODEL_DIR.mkdir(parents=True, exist_ok=True)

MODEL_PATH = MODEL_DIR / "intent_model.pt"
VECTORIZER_PATH = MODEL_DIR / "intent_vectorizer.pkl"
LABELS_PATH = MODEL_DIR / "intent_labels.json"
METRICS_PATH = MODEL_DIR / "intent_metrics.json"

SEED = 42


class IntentNet(nn.Module):
    """Small MLP. Kept deliberately shallow — 344 examples cannot support
    anything deeper without memorising the training set."""

    def __init__(self, in_dim: int, n_classes: int, hidden: int = 256):
        super().__init__()
        self.net = nn.Sequential(
            nn.Linear(in_dim, hidden),
            nn.ReLU(),
            nn.Dropout(0.3),
            nn.Linear(hidden, hidden // 2),
            nn.ReLU(),
            nn.Dropout(0.2),
            nn.Linear(hidden // 2, n_classes),
        )

    def forward(self, x):
        return self.net(x)


def build_features(train_texts: list[str], all_texts: list[str]):
    """Fit TF-IDF on the training split only.

    Fitting on all texts would leak validation vocabulary into training and
    inflate the reported accuracy.
    """
    vec = TfidfVectorizer(
        analyzer="char_wb",
        ngram_range=(2, 5),
        min_df=1,
        sublinear_tf=True,
        lowercase=True,
    )
    word_vec = TfidfVectorizer(
        analyzer="word",
        ngram_range=(1, 2),
        min_df=1,
        sublinear_tf=True,
        lowercase=True,
    )
    vec.fit(train_texts)
    word_vec.fit(train_texts)
    return vec, word_vec


def transform(vec, word_vec, texts: list[str]) -> np.ndarray:
    a = vec.transform(texts).toarray()
    b = word_vec.transform(texts).toarray()
    return np.hstack([a, b]).astype(np.float32)


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--epochs", type=int, default=100)
    ap.add_argument("--lr", type=float, default=2e-3)
    ap.add_argument("--hidden", type=int, default=256)
    ap.add_argument("--val-size", type=float, default=0.2)
    ap.add_argument("--raw", action="store_true",
                    help="train on the small handwritten set instead of the augmented one")
    args = ap.parse_args()

    torch.manual_seed(SEED)
    np.random.seed(SEED)

    print("=" * 68)
    print("JARVIS INTENT CLASSIFIER — TRAINING".center(68))
    print("=" * 68)
    print()
    if args.raw:
        texts, labels = flatten()
        print(stats())
    else:
        texts, labels = flatten_augmented()
        from collections import Counter
        c = Counter(labels)
        print(f"Augmented dataset: {len(texts)} examples across {len(c)} classes")
        print(f"  per class: min={min(c.values())} "
              f"median={sorted(c.values())[len(c)//2]} max={max(c.values())}")
    print()

    le = LabelEncoder()
    y_all = le.fit_transform(labels)

    # Stratify so every class appears in both splits.
    X_tr_txt, X_va_txt, y_tr, y_va = train_test_split(
        texts, y_all, test_size=args.val_size, random_state=SEED, stratify=y_all
    )

    vec, word_vec = build_features(X_tr_txt, texts)
    X_tr = transform(vec, word_vec, X_tr_txt)
    X_va = transform(vec, word_vec, X_va_txt)

    print(f"  train examples : {len(X_tr_txt)}")
    print(f"  val examples   : {len(X_va_txt)}")
    print(f"  feature dim    : {X_tr.shape[1]}")
    print(f"  classes        : {len(le.classes_)}")
    print()

    # Class weighting — the catch-all class is 6x larger than the smallest.
    counts = np.bincount(y_tr, minlength=len(le.classes_)).astype(np.float32)
    counts[counts == 0] = 1.0
    weights = torch.tensor(counts.sum() / (len(counts) * counts), dtype=torch.float32)

    model = IntentNet(X_tr.shape[1], len(le.classes_), hidden=args.hidden)
    opt = torch.optim.Adam(model.parameters(), lr=args.lr, weight_decay=1e-4)
    sched = torch.optim.lr_scheduler.CosineAnnealingLR(opt, T_max=args.epochs)
    loss_fn = nn.CrossEntropyLoss(weight=weights)

    Xtr = torch.from_numpy(X_tr)
    Ytr = torch.from_numpy(y_tr).long()
    Xva = torch.from_numpy(X_va)
    Yva = torch.from_numpy(y_va).long()

    best_val = 0.0
    best_state = None
    history = []

    print(f"  Training for {args.epochs} epochs")
    print(f"  {'epoch':>6} {'loss':>9} {'train':>8} {'val':>8}")
    print("  " + "-" * 34)

    t0 = time.time()
    for epoch in range(1, args.epochs + 1):
        model.train()
        opt.zero_grad()
        out = model(Xtr)
        loss = loss_fn(out, Ytr)
        loss.backward()
        opt.step()
        sched.step()

        model.eval()
        with torch.no_grad():
            tr_acc = (model(Xtr).argmax(1) == Ytr).float().mean().item()
            va_logits = model(Xva)
            va_acc = (va_logits.argmax(1) == Yva).float().mean().item()

        history.append({"epoch": epoch, "loss": loss.item(),
                        "train_acc": tr_acc, "val_acc": va_acc})

        if va_acc >= best_val:
            best_val = va_acc
            best_state = {k: v.clone() for k, v in model.state_dict().items()}

        if epoch % 10 == 0 or epoch == 1:
            print(f"  {epoch:6} {loss.item():9.4f} {tr_acc:8.1%} {va_acc:8.1%}")

    elapsed = time.time() - t0
    print("  " + "-" * 34)
    print(f"  trained in {elapsed:.1f}s   best val accuracy: {best_val:.1%}")
    print()

    if best_state is not None:
        model.load_state_dict(best_state)

    # ── Persist ──────────────────────────────────────────────────────────
    torch.save(
        {
            "state_dict": model.state_dict(),
            "in_dim": X_tr.shape[1],
            "n_classes": len(le.classes_),
            "hidden": args.hidden,
        },
        MODEL_PATH,
    )
    with open(VECTORIZER_PATH, "wb") as f:
        pickle.dump({"char": vec, "word": word_vec}, f)
    with open(LABELS_PATH, "w") as f:
        json.dump(list(le.classes_), f, indent=2)
    with open(METRICS_PATH, "w") as f:
        json.dump(
            {
                "best_val_accuracy": best_val,
                "epochs": args.epochs,
                "train_size": len(X_tr_txt),
                "val_size": len(X_va_txt),
                "feature_dim": int(X_tr.shape[1]),
                "n_classes": len(le.classes_),
                "trained_at": time.strftime("%Y-%m-%d %H:%M:%S"),
                "augmented": not args.raw,
                "history": history[-20:],
            },
            f,
            indent=2,
        )

    size_kb = MODEL_PATH.stat().st_size / 1024
    print(f"  saved model      -> {MODEL_PATH.name}  ({size_kb:.0f} KB)")
    print(f"  saved vectorizer -> {VECTORIZER_PATH.name}")
    print(f"  saved labels     -> {LABELS_PATH.name}")
    print()

    # ── Per-class report on the validation split ─────────────────────────
    model.eval()
    with torch.no_grad():
        preds = model(Xva).argmax(1).numpy()
    print("  Misclassified validation examples:")
    wrong = 0
    for txt, true_i, pred_i in zip(X_va_txt, y_va, preds):
        if true_i != pred_i:
            wrong += 1
            print(f"    {txt!r:44} {le.classes_[true_i]} -> {le.classes_[pred_i]}")
    if not wrong:
        print("    (none)")
    print()

    # ── Confidence gating ────────────────────────────────────────────────
    # The model should not answer when it is unsure; the router can fall back
    # to the Groq LLM instead. This finds the softmax threshold where the
    # model is reliable enough to trust on its own.
    with torch.no_grad():
        probs = torch.softmax(model(Xva), dim=1)
        conf, pred = probs.max(dim=1)
    conf = conf.numpy()
    pred = pred.numpy()
    correct = (pred == y_va)

    print("  Confidence gating (val split)")
    print(f"    {'threshold':>10} {'coverage':>10} {'accuracy':>10}   {'verdict'}")
    chosen = None
    for thr in (0.0, 0.5, 0.6, 0.7, 0.8, 0.9, 0.95):
        mask = conf >= thr
        cov = mask.mean()
        acc = correct[mask].mean() if mask.sum() else 0.0
        note = ""
        # Prefer the LOWEST threshold that is essentially never wrong while
        # still covering most traffic. Accepting 95% here would pick 0.0 and
        # throw away the whole point of gating.
        if acc >= 0.99 and cov >= 0.5 and chosen is None:
            chosen = thr
            note = "  <== gate here"
        print(f"    {thr:>10.2f} {cov:>9.1%} {acc:>10.1%}{note}")
    print()
    if chosen is not None:
        mask = conf >= chosen
        print(f"    At threshold {chosen}: {mask.mean():.0%} of utterances answered "
              f"locally at {correct[mask].mean():.0%} accuracy;")
        print(f"    the remaining {1 - mask.mean():.0%} fall through to the LLM.")
    else:
        print("    No threshold reaches 99% accuracy with useful coverage.")
    print()

    # Persist the gate alongside the other metrics. Written here rather than
    # in the earlier dump because `chosen` only exists after this analysis.
    with open(METRICS_PATH) as f:
        _m = json.load(f)
    _m["confidence_gate"] = chosen if chosen is not None else 0.7
    with open(METRICS_PATH, "w") as f:
        json.dump(_m, f, indent=2)

    # ── Latency benchmark: the entire point of this model ────────────────
    samples = ["what time is it", "open spotify", "tell me a joke",
               "who is alan turing", "how do i write async python"]
    Xs = transform(vec, word_vec, samples)
    Xs_t = torch.from_numpy(Xs)
    with torch.no_grad():
        model(Xs_t)  # warm up
        t = time.perf_counter()
        for _ in range(200):
            model(Xs_t)
        per_batch = (time.perf_counter() - t) / 200
    per_utterance_ms = (per_batch / len(samples)) * 1000

    print("  Inference latency")
    print(f"    local model : {per_utterance_ms:.3f} ms per utterance")
    print(f"    Groq LLM    : ~350-500 ms (network round trip)")
    if per_utterance_ms > 0:
        print(f"    speedup     : ~{350 / per_utterance_ms:,.0f}x")
    print()
    print("=" * 68)
    return 0


if __name__ == "__main__":
    sys.exit(main())
